package typescript

import (
	"context"
	"path/filepath"
	"reflect"
	"testing"

	"github.com/graphvein/graphvein/internal/lang/facts"
	"github.com/graphvein/graphvein/internal/parse"
)

// TestAutoImports checks the declaration forms row UP-41 reads from a
// declaration file generated by unplugin-auto-import, and that every other
// form records nothing.
func TestAutoImports(t *testing.T) {
	parsed := func(source string) *parse.Node {
		results, err := parse.Batch(context.Background(), []parse.Job{{Language: "typescript", Source: []byte(source)}}, parse.Options{CacheDir: filepath.Join(t.TempDir(), "cache")})
		if err != nil || results[0].Err != nil {
			t.Fatal(results, err)
		}
		return results[0].Root
	}
	body := `export {}
declare global {
  const withBase: typeof import('./stores/config').withBase
  const parent: typeof import('../lib/api').parent
  const lookup: typeof import('./stores/config')['lookup']
  const renamed: typeof import('./stores/config').other
  const pkg: typeof import('vue').pkg
  let mutable: typeof import('./stores/config').mutable
}
`
	header := "/* eslint-disable */\n// Generated by unplugin-auto-import\n"
	for _, tc := range []struct {
		file, source string
		want         []facts.AutoImport
	}{
		{"auto-imports.d.ts", header + body, []facts.AutoImport{{Name: "withBase", Module: "./stores/config"}, {Name: "parent", Module: "../lib/api"}}},
		{"auto-imports.d.ts", body, nil},
		{"auto-imports.ts", header + body, nil},
	} {
		var r facts.RouteFacts
		cacheGlobalNames(tc.file, parsed(tc.source), &r)
		if !reflect.DeepEqual(r.AutoImports, tc.want) {
			t.Errorf("%s: %+v, want %+v", tc.file, r.AutoImports, tc.want)
		}
	}
}
